<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Orchard Catch Arcade</title>
<style>

:root{
  /* Arcade Palette Override */
  --bg:#0a140d;
  --surface:#152619;
  --ink:#e8f5e9;
  --muted:#8fa893;
  --accent:#6BBF59;
  --accent-glow:rgba(107, 191, 89, 0.6);
  --accent-2:#d9a441;
  --danger:#ff3333;
  --line:#2d4a35;
  --radius:4px; /* Sharper arcade corners */
  --shadow:0 0 15px rgba(107, 191, 89, 0.2);

  /* CRT Effect Variables */
  --scanline-color:rgba(0, 0, 0, 0.3);
}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background-color: var(--bg)}
body{
  min-height:100vh;
  color:var(--ink);
  font-family:"Trebuchet MS",Verdana,"Segoe UI",sans-serif;
  display:flex;justify-content:center;padding:16px;
  overflow-x:hidden;
}
.skip-link{position:absolute;left:-9999px;top:0;background:#fff;padding:10px 14px;border-radius:8px;z-index:50}
.skip-link:focus{left:12px;top:12px}
.app{width:100%;max-width:960px;display:flex;flex-direction:column;gap:18px}
h1{font-size:clamp(1.3rem,2.4vw,1.9rem);margin:0;line-height:1.15;text-transform:uppercase;letter-spacing:2px;color:var(--accent);text-shadow:0 0 10px var(--accent-glow)}
.tagline{margin:6px 0 0;color:var(--muted);font-size:.95rem;font-style:italic}

/* Arcade Panel Styling */
.panel{background:var(--surface);border:2px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:18px;position:relative}
.panel::before {
  content:""; position:absolute; inset:0; border-radius:inherit; opacity:0.1; pointer-events:none;
  background: repeating-linear-gradient(0deg, transparent, transparent 2px, var(--ink) 3px);
}

.brand{display:flex;flex-direction:column;gap:2px}
.stats{display:flex;gap:12px;flex-wrap:wrap;margin:0}
.stat{min-width:104px;background:#0f1c12;border:1px solid var(--line);border-radius:8px;padding:8px 12px}
.stat dt{font-size:.72rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin:0}
.stat dd{margin:2px 0 0;font-size:1.15rem;font-weight:700;color:var(--accent)}

.stage{
  position:relative;overflow:hidden;border-radius:8px;border:4px solid var(--line);
  background:linear-gradient(180deg, #0f1c12 0%, #1a2e1d 100%);
  min-height:360px;touch-action:none; user-select:none;
}
/* Scanline overlay */
.stage::after {
  content:""; position:absolute; inset:0; pointer-events:none; z-index:10;
  background: linear-gradient(to bottom, var(--scanline-color) 50%, transparent 50%);
  background-size: 100% 4px;
  opacity: 0.3;
}
.stage:focus-visible{outline:3px solid var(--accent-2);outline-offset:-6px}

/* Arcade Basket */
.basket{position:absolute;bottom:20px;left:50%;width:110px;height:40px;transform:translateX(-50%);z-index:3}
.basket::before{content:"";position:absolute;inset:0;background:#2d4a35;border-radius:6px;border-bottom:4px solid var(--accent);box-shadow:0 0 15px var(--accent-glow)}
.basket::after{content:"";position:absolute;left:50%;top:-10px;transform:translateX(-50%);width:20px;height:10px;background:var(--accent-2);border-radius:4px}

.fruit-layer{position:absolute;inset:0;z-index:2;pointer-events:none}
.fruit{position:absolute;width:36px;height:36px;border-radius:50%;box-shadow:0 0 10px rgba(255,255,255,0.2);border:2px solid rgba(255,255,255,0.4)}
.fruit-0{background:#ff3333; box-shadow:0 0 10px #ff3333} /* Red */
.fruit-1{background:#ffaa00; box-shadow:0 0 10px #ffaa00} /* Orange */
.fruit-2{background:#aa55ff; box-shadow:0 0 10px #aa55ff} /* Purple */
.fruit-3{background:#ffff00; box-shadow:0 0 10px #ffff00} /* Gold */
.fruit-star{background:#fff; border-color:var(--accent); box-shadow:0 0 20px var(--accent), inset 0 0 10px var(--accent)}

/* Particles */
.particle { position:absolute; width:6px; height:6px; background:var(--accent); border-radius:50%; pointer-events:none; z-index:4; }

.overlay{position:fixed;inset:0;background:rgba(10, 20, 13, 0.9);display:flex;align-items:center;justify-content:center;padding:20px;z-index:40;backdrop-filter:blur(4px)}
.overlay[hidden]{display:none}
.overlay-panel{background:#152619;border:2px solid var(--accent);border-radius:8px;padding:30px;max-width:480px;width:100%;text-align:center;box-shadow:0 0 30px rgba(107, 191, 89, 0.3)}
.overlay-panel h2{margin:0 0 12px;font-size:2rem;color:#fff;text-transform:uppercase;letter-spacing:2px}
.overlay-panel p{margin:0 0 24px;color:var(--muted);font-size:1.1rem}

.message{margin:0;min-height:1.5em;background:#0f1c12;border-left:4px solid var(--accent);border-radius:0 4px 4px 0;padding:10px 14px;font-weight:bold;color:var(--accent);text-transform:uppercase}
.btn{appearance:none;border:2px solid var(--line);background:#152619;color:var(--ink);font:inherit;font-weight:700;text-transform:uppercase;letter-spacing:1px;padding:12px 24px;border-radius:4px;cursor:pointer;min-height:48px;transition:all 0.1s}
.btn:hover{background:#2d4a35;border-color:var(--accent)}
.btn:focus-visible{outline:3px solid var(--accent-2);outline-offset:2px}
.btn--solid{background:var(--accent);border-color:var(--accent);color:#000;box-shadow:0 0 15px var(--accent-glow)}
.btn--solid:hover{background:#8fd47a}

.meter{height:16px;border-radius:4px;background:#0f1c12;overflow:hidden;border:1px solid var(--line)}
.meter-fill{display:block;height:100%;width:0;background:var(--accent);transition:width .1s linear;box-shadow:0 0 10px var(--accent-glow)}

.chips{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:12px}
.chip{background:#0f1c12;border:1px solid var(--line);border-radius:4px;padding:6px 12px;font-size:.85rem;color:var(--muted)}
.chip strong{color:var(--accent)}

.log{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;max-height:200px;overflow:auto}
.log li{font-size:.8rem;color:var(--muted);border-left:3px solid var(--line);padding:4px 8px;font-family:monospace}
.toast{position:fixed;right:18px;top:18px;z-index:45;max-width:280px;background:#152619;border:1px solid var(--accent);border-radius:8px;padding:12px 14px;box-shadow:var(--shadow);font-size:.92rem;color:var(--ink)}
.toast[hidden]{display:none}

.dock{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.rail{display:flex;flex-direction:column;gap:14px}
.lane-marker{position:absolute;left:0;right:0;border-top:1px dashed rgba(107, 191, 89, 0.2)}
.lane-label{position:absolute;left:12px;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:rgba(107, 191, 89, 0.5);background:rgba(0,0,0,.6);border-radius:4px;padding:2px 8px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.lede{margin:0;color:var(--muted);font-size:.95rem}

@media (max-width:640px){body{padding:10px}.stage{min-height:320px}}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}

.t01{display:grid;grid-template-columns:250px minmax(0,1fr);gap:18px;align-items:start}
