/* Shared Design System Overrides for Arcade */
body{line-height:1.5}
::selection{background:var(--accent);color:#000}
h1,h2,h3{font-weight:800;letter-spacing:-.01em}
p{margin:0 0 .5rem}
p:last-child{margin-bottom:0}
