<body>
<a class="skip-link" href="#main">Skip to game</a><div class="app t01"><aside class="rail panel" aria-label="Game controls"><div class="brand"><h1>Orchard Catch</h1><p class="lede">Arcade Edition.</p></div><dl class="stats stats--stack" aria-label="Game statistics"><div class="stat"><dt>Lives</dt><dd data-s02="lives">3</dd></div><div class="stat"><dt>Score</dt><dd data-s02="score">0</dd></div><div class="stat"><dt>Combo</dt><dd data-s02="combo">x1</dd></div></dl><p class="message" data-s02="message" aria-live="polite">Press Start to Play.</p><button type="button" class="btn btn--ghost" data-s02="restart">Reset Game</button><div class="chips"><span class="chip">Mouse: <strong>Move</strong></span><span class="chip">Keys: <strong>Arrows</strong></span><span class="chip">Touch: <strong>Swipe</strong></span></div></aside><main class="play" id="main"><div class="stage" data-s02="stage" tabindex="0" role="application" aria-label="Fruit-catching stage; move the basket with the mouse, arrow keys or a tap"><div class="fruit-layer" data-s02="fruits"></div><div class="basket" data-s02="basket" aria-hidden="true"></div></div></main><div class="overlay" data-s02="overlay" hidden><div class="overlay-panel"><h2 id="game-title">Orchard Catch</h2><p data-s02="detail">Catch the falling fruit. Avoid missing.</p><button type="button" class="btn btn--solid" data-s02="playagain">Start Game</button></div></div></div>
<script>

(function () {
  'use strict';

  // --- Configuration & State ---
  var CFG = {
    "goal": 100,          // Score to win (or infinite mode)
    "input": "keys",      // Default input type
    "pitch": 800,         // Initial spawn rate (ms)
    "seed": 2202,
    "speed": 3.5,         // Base speed multiplier
    "maxLives": 3
  };

  function all(role) { return Array.prototype.slice.call(document.querySelectorAll('[data-s02="' + role + '"]')); }
  function one(role) { return document.querySelector('[data-s02="' + role + '"]'); }
  function set(role, text) { all(role).forEach(function (node) { node.textContent = String(text); }); }

  // Event Emitter for External Integration
  var S02 = window.S02 = window.S02 || { onCatch: [], onMiss: [], onWin: [], onRestart: [] };
  function emit(name, data) { (S02[name] || []).forEach(function (fn) { try { fn(data); } catch (err) {} }); }

  // --- Game Variables ---
  var seed = CFG.seed >>> 0;
  function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed; }

  var state = {
    score: 0,
    lives: CFG.maxLives,
    combo: 0,
    highScore: 0,
    won: false,
    active: false,
    fruits: [],
    particles: [],
    spawnAt: 0,
    last: 0,
    difficulty: 1
  };

  var basketX = 0;

  // --- Helpers ---
  function stageSize() { 
    var stage = one('stage'); 
    return { w: stage.clientWidth || 640, h: stage.clientHeight || 380 }; 
  }

  function paint() {
    set('score', state.score);
    set('lives', state.lives);
    set('combo', 'x' + Math.max(1, state.combo));

    // Update Meter (Visual progress bar)
    var meter = one('meter'); 
    if (meter) { 
      var pct = Math.min(100, (state.score / CFG.goal) * 100);
      meter.style.width = pct + '%'; 
    }

    // Color feedback for combo
    var comboEl = one('combo');
    if(comboEl) {
      if(state.combo > 5) comboEl.style.color = '#ffff00';
      else if(state.combo > 2) comboEl.style.color = '#ffaa00';
      else comboEl.style.color = 'var(--accent)';
    }
  }

  function createParticle(x, y, color) {
    var p = document.createElement('div');
    p.className = 'particle';
    p.style.left = x + 'px';
    p.style.top = y + 'px';
    p.style.background = color;
    one('fruits').appendChild(p);

    // Physics for particle
    var angle = rand() % 360;
    var speed = 1 + (rand() % 4);
    state.particles.push({
      node: p,
      x: parseFloat(p.style.left),
      y: parseFloat(p.style.top),
      vx: Math.cos(angle * Math.PI / 180) * speed,
      vy: Math.sin(angle * Math.PI / 180) * speed,
      life: 1.0
    });
  }

  function updateParticles() {
    for (var i = state.particles.length - 1; i >= 0; i--) {
      var p = state.particles[i];
      p.life -= 0.05;
      p.x += p.vx;
      p.y += p.vy;

      if (p.life <= 0) {
        if (p.node.parentNode) p.node.parentNode.removeChild(p.node);
        state.particles.splice(i, 1);
      } else {
        p.node.style.left = p.x + 'px';
        p.node.style.top = p.y + 'px';
        p.node.style.opacity = p.life;
      }
    }
  }

  function moveBasket(x) {
    var basket = one('basket'); 
    if (!basket) return;
    var size = stageSize();
    // Clamp within bounds, accounting for half width (approx 55px)
    basketX = Math.max(55, Math.min(size.w - 55, x));
    basket.style.left = basketX + 'px';
  }

  function spawn() {
    var size = stageSize();
    var fruit = document.createElement('div');

    // Determine type (0-3 normal, 4 special star)
    var kind = rand() % 5; 
    if (kind === 4 && state.score > 20) {
      fruit.className = 'fruit fruit-star';
    } else {
      fruit.className = 'fruit fruit-' + (kind < 4 ? kind : 0);
    }

    // Position
    var x = 30 + (rand() % Math.max(60, size.w - 60));

    // Speed increases with score
    var speedMultiplier = 1 + (state.score / 200); 
    var baseSpeed = CFG.speed * speedMultiplier;
    var speed = (baseSpeed + (rand() % 3) * 0.5);

    fruit.style.left = x + 'px'; 
    fruit.style.top = '-40px';

    one('fruits').appendChild(fruit);
    state.fruits.push({ node: fruit, x: x, y: -40, speed: speed, radius: 18, type: kind });
  }

  function removeFruit(index) {
    var item = state.fruits[index];
    if (item && item.node && item.node.parentNode) { 
      item.node.parentNode.removeChild(item.node); 
    }
    state.fruits.splice(index, 1);
  }

  function miss(index) {
    removeFruit(index); 
    state.lives -= 1;
    state.combo = 0; // Reset combo
    paint();

    var msg = one('message');
    if(state.lives <= 0) {
      set('message', 'GAME OVER! Press Start.');
      endGame(false);
    } else {
      set('message', 'Missed! Lives: ' + state.lives);
      // Shake effect
      var stage = one('stage');
      if(stage) {
        stage.style.transform = 'translateX(5px)';
        setTimeout(function(){ stage.style.transform = 'translateX(-5px)'; }, 50);
        setTimeout(function(){ stage.style.transform = 'none'; }, 100);
      }
    }
    emit('onMiss', { lives: state.lives, score: state.score });
  }

  function catchFruit(index) {
    var item = state.fruits[index];
    removeFruit(index); 

    // Scoring Logic
    state.combo++;
    var points = 10 * Math.max(1, Math.floor(state.combo / 2));

    // Star fruit bonus
    if (item.type === 4) {
      points += 50;
      set('message', 'STAR! +' + points);
      state.lives = Math.min(CFG.maxLives, state.lives + 1); // Revive life
    } else {
      set('message', 'Caught! +' + points);
    }

    state.score += points;

    // Particles
    var colors = ['#ff3333','#ffaa00','#aa55ff','#ffff00'];
    for(var i=0; i<8; i++) {
      createParticle(item.x, item.y, colors[rand() % 4]);
    }

    paint();
    emit('onCatch', { score: state.score, combo: state.combo });

    if (state.score >= CFG.goal) {
      win();
    }
  }

  function win() {
    endGame(true);
  }

  function endGame(winState) {
    state.won = true;
    state.active = false;
    var overlay = one('overlay');
    if (overlay) { 
      overlay.hidden = false; 
      var title = document.getElementById('game-title');
      var detail = one('detail');
      var btn = one('playagain');

      if (winState) {
        title.textContent = "YOU WIN!";
        title.style.color = "#6BBF59";
        detail.textContent = "Final Score: " + state.score;
        btn.textContent = "Play Again";
      } else {
        title.textContent = "GAME OVER";
        title.style.color = "#ff3333";
        detail.textContent = "Score: " + state.score;
        btn.textContent = "Try Again";
      }
    }
    emit('onWin', { score: state.score, win: winState });
  }

  function restart() {
    // Clear DOM
    while (state.fruits.length) { removeFruit(0); }
    updateParticles(); // This will clean up particles

    // Reset State
    state.score = 0;
    state.lives = CFG.maxLives;
    state.combo = 0;
    state.won = false;
    state.active = true;
    state.last = 0; 
    state.spawnAt = 0;

    var size = stageSize(); 
    basketX = size.w / 2; 
    moveBasket(basketX);

    paint(); 
    set('message', 'Catch the fruit!');

    var overlay = one('overlay'); 
    if (overlay) { overlay.hidden = true; }

    emit('onRestart', {});
    window.requestAnimationFrame(step);
  }

  // --- Main Loop ---
  function step(timestamp) {
    if (!state.active) return;

    var size = stageSize();
    if (!state.last) state.last = timestamp;
    var elapsed = Math.min(60, timestamp - state.last); 
    state.last = timestamp;

    // Spawn Logic (Dynamic difficulty)
    // As score goes up, pitch decreases (spawns faster)
    var currentPitch = Math.max(300, CFG.pitch - (state.score * 2));

    if (timestamp >= state.spawnAt) { 
      spawn(); 
      state.spawnAt = timestamp + currentPitch; 
    }

    // Update Fruits
    for (var i = state.fruits.length - 1; i >= 0; i -= 1) {
      var item = state.fruits[i];
      item.y += item.speed * (elapsed / 16.67);
      item.node.style.top = item.y + 'px';

      // Missed bottom
      if (item.y > size.h + 30) { 
        miss(i); 
        continue; 
      }

      // Collision Logic
      // Basket Y is roughly size.h - 60. Basket height is ~40.
      var basketTop = size.h - 60;
      var basketBottom = size.h - 20;

      if (item.y + item.radius >= basketTop && item.y <= basketBottom) {
        // Check X overlap
        if (Math.abs((item.x + item.radius/2) - basketX) < 55) {
          catchFruit(i); 
        }
      }
    }

    updateParticles();
    window.requestAnimationFrame(step);
  }

  // --- Input Handling ---
  var stage = one('stage');
  if (stage) {
    // Pointer Move (Mouse Drag / Touch Move)
    stage.addEventListener('pointermove', function (event) {
      event.preventDefault(); // Prevent scrolling on touch
      var rect = stage.getBoundingClientRect(); 
      moveBasket(event.clientX - rect.left);
    });

    // Pointer Down (Tap/Click to jump or just focus)
    stage.addEventListener('pointerdown', function (event) {
      if (state.active) return; // Let overlay handle clicks
      var rect = stage.getBoundingClientRect(); 
      moveBasket(event.clientX - rect.left);
    });

    // Keyboard Controls
    stage.addEventListener('keydown', function (event) {
      if (CFG.input === 'pointer') return;

      if (event.key === 'ArrowLeft') { 
        event.preventDefault(); 
        moveBasket(basketX - 20); 
      }
      if (event.key === 'ArrowRight') { 
        event.preventDefault(); 
        moveBasket(basketX + 20); 
      }
    });

    // Touch Swipe Support for Arcade feel
    var touchStartX = 0;
    stage.addEventListener('touchstart', function(e) {
      touchStartX = e.changedTouches[0].screenX;
    }, {passive: false});

    stage.addEventListener('touchmove', function(e) {
      // Prevent default to stop scrolling while playing
      if(state.active) e.preventDefault(); 
    }, {passive: false});

    stage.addEventListener('touchend', function(e) {
       var touchEndX = e.changedTouches[0].screenX;
       var diff = touchEndX - touchStartX;
       if (Math.abs(diff) > 30) { // Threshold for swipe
          moveBasket(basketX + (diff > 0 ? 40 : -40));
       }
    });
  }

  // --- Initialization ---
  all('restart').forEach(function (button) { button.addEventListener('click', restart); });
  all('playagain').forEach(function (button) { 
    button.addEventListener('click', function() {
      // Reset overlay to start state if needed, then restart
      var title = document.getElementById('game-title');
      if(title.textContent === "YOU WIN!") {
        title.textContent = "Orchard Catch";
        title.style.color = "#e8f5e9";
      }
      restart(); 
    }); 
  });

  // Initial Setup
  var initial = stageSize(); 
  basketX = initial.w / 2; 
  moveBasket(basketX); 
  paint();

  // Start Loop (paused initially via state.active)
  window.requestAnimationFrame(step);

})();


